const AREA: &str = "model/couplers";
const NG: GhostType = GhostType::NotGhost;

fn param(f: &Fixture, name: &str) -> serde_json::Value {
    f.manifest()
        .parameters
        .get(name)
        .cloned()
        .unwrap_or_else(|| panic!("{}: no parameter {name}", f.case_id()))
}

fn eigen_static() -> ModelOptions {
    ModelOptions::new(AnalysisMethod::Static).with_solver_options(ModelSolverOptions {
        non_linear_solver_type: Some(NonLinearSolverType::Auto),
        sparse_solver_type: Some(SparseSolverType::Eigen),
        ..ModelSolverOptions::default()
    })
}

fn solver_id(f: &Fixture, name: &str) -> Option<String> {
    let s = param(f, name).as_str().unwrap().to_owned();
    if s.is_empty() { None } else { Some(s) }
}

fn set_newton(f: &Fixture, who: &str, nls: &mut dyn akantu_solver::NonLinearSolver) {
    if !param(f, &format!("{who}_newton_set")).as_bool().unwrap() {
        return;
    }
    let it = param(f, &format!("{who}_newton_max_iterations"))
        .as_i64()
        .unwrap();
    let thr = param(f, &format!("{who}_newton_threshold"))
        .as_f64()
        .unwrap();
    let crit = param(f, &format!("{who}_newton_convergence_type"))
        .as_str()
        .unwrap()
        .to_owned();
    nls.set_param("max_iterations", ParamValue::Int(it))
        .unwrap();
    nls.set_param("threshold", ParamValue::Real(thr)).unwrap();
    nls.set_param("convergence_type", ParamValue::Enum(crit))
        .unwrap();
}

fn newton_state(nls: &dyn akantu_solver::NonLinearSolver) -> (i64, f64) {
    let it = match nls.get_param("nb_iterations").unwrap() {
        ParamValue::Int(i) => i,
        other => panic!("nb_iterations: {other:?}"),
    };
    let err = match nls.get_param("error").unwrap() {
        ParamValue::Real(e) => e,
        other => panic!("error: {other:?}"),
    };
    (it, err)
}

