/* solid – phase field                                                     */
/* ---------------------------------------------------------------------- */

/// `applyDisplacement` of the upstream tests.
fn apply_displacement(c: &mut CouplerSolidPhaseField, eps: Real, bottom: Real, top: Real) {
    let nodes = c.solid.physics.base.mesh.read().unwrap().nodes().clone();
    let mut u = c.solid.displacement().unwrap().as_slice().to_vec();
    let mut b = c.solid.blocked_dofs().unwrap().as_slice().to_vec();
    for (n, x) in nodes.as_slice().as_chunks::<2>().0.iter().enumerate() {
        if x[1] == bottom {
            u[2 * n] = 0.;
            u[2 * n + 1] = 0.;
            b[2 * n] = true;
            b[2 * n + 1] = true;
        } else if x[1] == top {
            u[2 * n] = 0.;
            u[2 * n + 1] = eps;
            b[2 * n] = true;
            b[2 * n + 1] = true;
        } else {
            u[2 * n] = 0.;
            b[2 * n] = true;
        }
    }
    c.solid
        .displacement_mut()
        .unwrap()
        .as_mut_slice()
        .copy_from_slice(&u);
    c.solid
        .blocked_dofs_mut()
        .unwrap()
        .as_mut_slice()
        .copy_from_slice(&b);
}

fn types_of(filter: &akantu_core::ElementTypeMapArray<akantu_core::Idx>) -> Vec<ElementType> {
    filter
        .element_types(akantu_core::TypeFilter {
            spatial_dimension: Some(2),
            ghost_type: NG,
            kind: None,
        })
        .collect()
}

fn material_internal(c: &CouplerSolidPhaseField, i: usize, name: &str) -> Vec<f64> {
    let m = c.solid.material(i).unwrap();
    let mut out = Vec::new();
    for ty in types_of(m.element_filter()) {
        m.for_each_internal(&mut |n, f| {
            if n == name
                && let InternalFieldRef::Real(f) = f
            {
                out.extend_from_slice(f.get(ty, NG).unwrap().as_slice());
            }
        });
    }
    out
}

fn law_internal(c: &CouplerSolidPhaseField, l: usize, name: &str, previous: bool) -> Vec<f64> {
    let law = c.phase.phase_field(l).unwrap();
    let mut out = Vec::new();
    for ty in types_of(law.element_filter()) {
        law.for_each_internal(&mut |n, f| {
            if n == name
                && let InternalFieldRef::Real(f) = f
            {
                if previous {
                    out.extend_from_slice(f.previous(ty, NG).unwrap().as_slice());
                } else {
                    out.extend_from_slice(f.get(ty, NG).unwrap().as_slice());
                }
            }
        });
    }
    out
}

fn compare_pf_state(f: &Fixture, c: &CouplerSolidPhaseField, prefix: &str) -> usize {
    let cid = f.case_id().to_owned();
    let mut n = 0;
    let mut cmp = |what: String, got: &[f64]| {
        let e = f64s(f, &what);
        assert_bits(&cid, &what, got, &e);
        n += e.len();
    };
    cmp(
        format!("{prefix}/displacement"),
        c.solid.displacement().unwrap().as_slice(),
    );
    cmp(
        format!("{prefix}/damage"),
        c.phase.damage().unwrap().as_slice(),
    );
    cmp(
        format!("{prefix}/internal_force"),
        c.solid.internal_force().unwrap().as_slice(),
    );
    for i in 0..c.solid.nb_materials() {
        for what in ["damage", "stress", "grad_u"] {
            cmp(
                format!("{prefix}/material/{i}/{what}"),
                &material_internal(c, i, what),
            );
        }
    }
    for l in 0..c.phase.nb_phase_fields() {
        cmp(
            format!("{prefix}/law/{l}/damage"),
            &law_internal(c, l, "damage", false),
        );
        cmp(
            format!("{prefix}/law/{l}/previous_damage"),
            &law_internal(c, l, "damage", true),
        );
        cmp(
            format!("{prefix}/law/{l}/strain"),
            &law_internal(c, l, "strain", false),
        );
        cmp(
            format!("{prefix}/law/{l}/phi"),
            &law_internal(c, l, "phi", false),
        );
    }
    n
}

/// Replay of a `pf_*` case through the port's coupler with every upstream
/// switch of the coupled phase-field path: coupler UD-382/619/620,
/// phase field UD-377…380, solid laws `LawOptions::upstream()` (the
/// `phasefield` material's tangent, which drives the solid Newton path).
fn replay_pf(f: &Fixture, upstream: bool) -> usize {
    replay_pf_with(f, upstream, None)
}

/// The coupler of a `pf_*` case, initialised as the probe does (the
/// upstream switches as for [`replay_pf`] when `upstream`, then the
/// phase-field switches replaced by `phase_compat`).
fn build_pf(
    f: &Fixture,
    upstream: bool,
    phase_compat: Option<akantu_phase_field::PhaseFieldUpstreamCompat>,
) -> CouplerSolidPhaseField {
    let cid = f.case_id().to_owned();
    let mesh = read_mesh(&f.input_path("mesh").unwrap(), 2);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    let mut c = CouplerSolidPhaseField::with_parser(
        SharedMesh::new(mesh),
        None,
        "coupler_solid_phasefield",
        parser,
    )
    .unwrap();
    if upstream {
        c.set_upstream_compat(true);
        c.solid.physics.law_options = Some(LawOptions::upstream());
    }
    if let Some(pc) = phase_compat {
        c.phase.set_upstream_compat(pc);
    }
    if param(f, "material_selector_physical_names")
        .as_bool()
        .unwrap()
    {
        c.solid
            .set_material_selector(Box::new(ElementDataSelector::new("physical_names")));
    }
    let explicit = param(f, "explicit_solid").as_bool().unwrap();
    if explicit {
        c.solid
            .init_full(&ModelOptions::new(AnalysisMethod::ExplicitLumpedMass))
            .unwrap();
    } else {
        c.solid.init_full(&eigen_static()).unwrap();
    }
    set_newton(
        f,
        "solid",
        c.solid.solver.non_linear_solver_mut(None).unwrap(),
    );
    if explicit {
        let dt = f64s(f, "time_step")[0];
        assert_bits(
            &cid,
            "time_step",
            &[c.solid.stable_time_step().unwrap() * 0.8],
            &[dt],
        );
        c.solid.set_time_step(dt, None).unwrap();
    }
    c.phase
        .set_phase_field_selector(Box::new(MeshDataPhaseFieldSelector::new("physical_names")));
    c.phase.init_full(&eigen_static()).unwrap();
    set_newton(
        f,
        "phase",
        c.phase.solver.non_linear_solver_mut(None).unwrap(),
    );
    assert_eq!(
        c.solid.nb_materials() as i64,
        param(f, "nb_materials").as_i64().unwrap()
    );
    assert_eq!(
        c.phase.nb_phase_fields() as i64,
        param(f, "nb_phase_fields").as_i64().unwrap()
    );
    c
}

/// The probe's per-step digest line: step, then SHA-256 of the solid
/// displacement, the nodal damage, the materials' damage and stress, the
/// laws' damage and strain.
fn pf_digest_line(s: usize, c: &CouplerSolidPhaseField) -> String {
    let mut md = Vec::new();
    let mut ms = Vec::new();
    for i in 0..c.solid.nb_materials() {
        md.extend(material_internal(c, i, "damage"));
        ms.extend(material_internal(c, i, "stress"));
    }
    let mut ld = Vec::new();
    let mut ls = Vec::new();
    for l in 0..c.phase.nb_phase_fields() {
        ld.extend(law_internal(c, l, "damage", false));
        ls.extend(law_internal(c, l, "strain", false));
    }
    format!(
        "{s} {} {} {} {} {} {}",
        sha_hex(c.solid.displacement().unwrap().as_slice()),
        sha_hex(c.phase.damage().unwrap().as_slice()),
        sha_hex(&md),
        sha_hex(&ms),
        sha_hex(&ld),
        sha_hex(&ls)
    )
}

/// [`replay_pf`] with the phase-field switches replaced by `phase_compat`
/// after the coupler's own mode is set.
fn replay_pf_with(
    f: &Fixture,
    upstream: bool,
    phase_compat: Option<akantu_phase_field::PhaseFieldUpstreamCompat>,
) -> usize {
    let cid = f.case_id().to_owned();
    let mut c = build_pf(f, upstream, phase_compat);
    let explicit = param(f, "explicit_solid").as_bool().unwrap();
    let sid = solver_id(f, "solid_solver_id");
    let pid = solver_id(f, "phase_solver_id");
    let save = param(f, "save_previous_state").as_bool().unwrap();
    let bottom = param(f, "bottom").as_f64().unwrap();
    let top = param(f, "top").as_f64().unwrap();
    let failure = f
        .manifest()
        .parameters
        .get("failure_step")
        .and_then(|v| v.as_i64());
    let schedule = f64s(f, "schedule/strain");
    let digests = read_input_text(f, "digests");
    let mut lines = digests.lines();
    let (mut s_it, mut s_err, mut p_it, mut p_err, mut e_diss, mut e_pot) = (
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
    );
    let mut compared = 0usize;
    for (s, &eps) in schedule.iter().enumerate() {
        apply_displacement(&mut c, eps, bottom, top);
        let r = c.solve(sid.as_deref(), pid.as_deref());
        if failure == Some(s as i64) {
            let e = r.expect_err("upstream failed at this step");
            let Error::NotConverged {
                threshold,
                niter,
                error,
            } = e
            else {
                panic!("{cid}: step {s}: expected NotConverged, got {e}");
            };
            assert_eq!(niter as i64, i64s(f, "failure/niter")[0], "{cid}: niter");
            assert_bits(&cid, "failure/error", &[error], &f64s(f, "failure/error"));
            assert_bits(
                &cid,
                "failure/threshold",
                &[threshold],
                &f64s(f, "failure/threshold"),
            );
            compared += 3;
            break;
        }
        r.unwrap_or_else(|e| panic!("{cid}: step {s}: {e}"));
        if !explicit {
            let (i, e) = newton_state(c.solid.solver.non_linear_solver(sid.as_deref()).unwrap());
            s_it.push(i);
            s_err.push(e);
        }
        let (i, e) = newton_state(c.phase.solver.non_linear_solver(pid.as_deref()).unwrap());
        p_it.push(i);
        p_err.push(e);
        e_diss.push(c.phase.energy("dissipated").unwrap());
        e_pot.push(c.solid.energy("potential").unwrap());
        if save {
            c.phase.save_previous_state().unwrap();
        }
        let got = pf_digest_line(s, &c);
        let line = lines
            .next()
            .unwrap_or_else(|| panic!("{cid}: no digest for step {s}"));
        if line != got {
            let ck = format!("step_{s}/displacement");
            if f.quantity(&ck).is_ok() {
                compare_pf_state(f, &c, &format!("step_{s}"));
            }
            panic!("{cid}: step {s}: digest mismatch\n  got      {got}\n  expected {line}");
        }
        compared += 6;
        if f.quantity(&format!("step_{s}/displacement")).is_ok() {
            compared += compare_pf_state(f, &c, &format!("step_{s}"));
        }
    }
    if !explicit {
        assert_eq!(
            s_it,
            i64s(f, "newton/solid_iterations"),
            "{cid}: solid iterations"
        );
        assert_bits(
            &cid,
            "newton/solid_error",
            &s_err,
            &f64s(f, "newton/solid_error"),
        );
    }
    assert_eq!(
        p_it,
        i64s(f, "newton/phase_iterations"),
        "{cid}: phase iterations"
    );
    assert_bits(
        &cid,
        "newton/phase_error",
        &p_err,
        &f64s(f, "newton/phase_error"),
    );
    assert_bits(
        &cid,
        "energy/dissipated",
        &e_diss,
        &f64s(f, "energy/dissipated"),
    );
    assert_bits(
        &cid,
        "energy/potential",
        &e_pot,
        &f64s(f, "energy/potential"),
    );
    compared += 2 * s_it.len() + 2 * p_it.len() + e_diss.len() + e_pot.len();
    compared += compare_pf_state(f, &c, "final");
    compared += compare_damage_storage(f, &c, upstream);
    compared
}

/// `final/material_damage_stored_sizes`: the stored
/// length of each material's `damage` block per element type. Upstream's
/// damage transfer copies the phase field's mesh-indexed interpolation into
/// the material's block (UD-382), which resizes it to the mesh block (two
/// quadrangles: 8 points) even when the material holds one element. The
/// port stores the material's own points: its compat mode reproduces the
/// values upstream's loops read (the prefix compared by
/// `compare_pf_state`), not that storage. So the sizes agree whenever the
/// material covers the whole type (one law per type, 6 of the 8 cases) and
/// differ, in compat mode, exactly by `stored = nb_element(type) · nq`
/// upstream versus `filter · nq` in the port otherwise.
fn compare_damage_storage(f: &Fixture, c: &CouplerSolidPhaseField, upstream: bool) -> usize {
    let cid = f.case_id();
    let expected = i64s(f, "final/material_damage_stored_sizes");
    let mesh_n = |ty| {
        use akantu_model::Model;
        c.solid.mesh().read().unwrap().nb_element(ty, NG) as i64
    };
    let mut k = 0;
    for i in 0..c.solid.nb_materials() {
        let m = c.solid.material(i).unwrap();
        for ty in types_of(m.element_filter()) {
            let mut got = 0i64;
            m.for_each_internal(&mut |n, fld| {
                if n == "damage"
                    && let InternalFieldRef::Real(fld) = fld
                {
                    got = fld.get(ty, NG).unwrap().len() as i64;
                }
            });
            let filter = m.element_filter().get(ty, NG).unwrap().len() as i64;
            assert!(
                filter > 0 && got % filter == 0,
                "{cid}: material {i}: points per element"
            );
            let nq = got / filter;
            let e = expected[k];
            if filter == mesh_n(ty) {
                assert_eq!(got, e, "{cid}: material {i} {ty:?}: damage storage");
            } else if upstream {
                // UD-382 compat: values read reproduced, storage not
                assert_eq!(
                    e,
                    mesh_n(ty) * nq,
                    "{cid}: material {i}: upstream stores the mesh block"
                );
                assert_eq!(
                    got,
                    filter * nq,
                    "{cid}: material {i}: port stores its own points"
                );
            } else {
                // corrected default: the material's own points (upstream's
                // storage is not a target)
                assert_eq!(got, filter * nq, "{cid}: material {i}: corrected storage");
            }
            k += 1;
        }
    }
    assert_eq!(
        k,
        expected.len(),
        "{cid}: one stored size per material and type"
    );
    expected.len()
}

/// The accuracy cases (probe version 3): the cells of the
/// acceptance table O4 (split × AT1 / AT2 × history / penalization) that the
/// version-1 cases do not run through the coupler.
const ACCEPTANCE_CASES: [&str; 4] = [
    "pf_linear_penalization",
    "pf_deviatoric_penalization",
    "pf_linear_deviatoric",
    "pf_linear_deviatoric_penalization",
];

#[test]
fn coupler_solid_phase_field_fixtures() {
    let all = cases(AREA, "pf_");
    assert_eq!(
        all.len(),
        12,
        "expected the 12 pf_* cases (8 coupler cases, 4 accuracy cases)"
    );
    for id in ACCEPTANCE_CASES {
        assert!(
            all.iter().any(|f| f.case_id().ends_with(&format!("/{id}"))),
            "missing case {id}"
        );
    }
    each_case(&all, |f| {
        let n = replay_pf(f, true);
        eprintln!("{}: {n} values bitwise", f.case_id());
    });
}

/// Run `replay` on every case, each in its own unwinding scope, so that one
/// failing case does not hide the others (the mutation runs of
/// Name every case that kills a mutant); fails at the end
/// with the list of failing cases and their messages.
fn each_case(all: &[Fixture], replay: impl Fn(&Fixture)) {
    let mut failed = Vec::new();
    for f in all {
        if let Err(e) = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| replay(f))) {
            let msg = e
                .downcast_ref::<String>()
                .cloned()
                .or_else(|| e.downcast_ref::<&str>().map(|s| (*s).to_owned()))
                .unwrap_or_default();
            let first = msg.lines().next().unwrap_or_default().to_owned();
            eprintln!("FAILED CASE {}: {first}", f.case_id());
            failed.push(format!("{}: {first}", f.case_id()));
        }
    }
    assert!(
        failed.is_empty(),
        "{} case(s) failed:\n{}",
        failed.len(),
        failed.join("\n")
    );
}

/// The phase-field switches a single-law `pf_*` case needs on top of the
/// corrected defaults to replay upstream bit for bit: UD-387
/// (`in_block_deviator_energy`, D-066 (2)) for the 2-D
/// volumetric–deviatoric driving energy, UD-388
/// (`at1_strict_irreversibility_indicator`) for the AT1 penalisation
/// tangent (upstream's strict `γ·[d < d_prev]`: after `savePreviousState`
/// every step starts at `d = d_prev`, where the corrected one-sided
/// derivative differs, so the Newton iterates differ).
fn pf_switches(case_id: &str) -> akantu_phase_field::PhaseFieldUpstreamCompat {
    let name = case_id.rsplit('/').next().unwrap_or(case_id);
    let deviatoric = matches!(
        name,
        "pf_deviatoric"
            | "pf_deviatoric_penalization"
            | "pf_linear_deviatoric"
            | "pf_linear_deviatoric_penalization"
    );
    let at1_penalization = matches!(
        name,
        "pf_linear_penalization" | "pf_linear_deviatoric_penalization"
    );
    akantu_phase_field::PhaseFieldUpstreamCompat {
        in_block_deviator_energy: deviatoric,
        at1_strict_irreversibility_indicator: at1_penalization,
        ..Default::default()
    }
}

/// The corrected defaults (coupler UD-382, phase field UD-377…380, solid
/// `LawOptions` defaults) give the same bits as upstream wherever one
/// phase field and one material cover each element type in mesh order:
/// every single-law case is replayed bitwise without any switch, except
/// where a phase-field default differs from upstream by design
/// ([`pf_switches`]): the 2-D volumetric–deviatoric cases
/// (`pf_deviatoric`, and the cases
/// `pf_deviatoric_penalization`, `pf_linear_deviatoric`,
/// `pf_linear_deviatoric_penalization`), where the corrected driving energy
/// differs from upstream's (UD-387, D-066 (2): `2/3 μ ε²` instead of
/// `5/9 μ ε²`, see phase_field_coupling.rs::test_phase_field_deviatoric_split),
/// and the AT1 penalisation cases (`pf_linear_penalization`,
/// `pf_linear_deviatoric_penalization`), whose corrected tangent differs
/// (UD-388); those cases are replayed with exactly those switches and every
/// other default corrected (what the full defaults change is measured by
/// [`coupler_solid_phase_field_default_mode_differences`]). The
/// multi-material cases differ by design (UD-382; see
/// phase_field_coupling.rs::test_multi_material).
#[test]
fn coupler_solid_phase_field_corrected_single_law_identical() {
    let single: Vec<Fixture> = cases(AREA, "pf_")
        .into_iter()
        .filter(|f| param(f, "nb_materials").as_i64().unwrap() == 1)
        .collect();
    let switches: Vec<_> = single.iter().map(|f| pf_switches(f.case_id())).collect();
    let n_ud387 = switches
        .iter()
        .filter(|s| s.in_block_deviator_energy)
        .count();
    let n_ud388 = switches
        .iter()
        .filter(|s| s.at1_strict_irreversibility_indicator)
        .count();
    assert_eq!((single.len(), n_ud387, n_ud388), (10, 4, 2));
    each_case(&single, |f| {
        let sw = pf_switches(f.case_id());
        let n = if sw == akantu_phase_field::PhaseFieldUpstreamCompat::default() {
            replay_pf(f, false)
        } else {
            replay_pf_with(f, false, Some(sw))
        };
        eprintln!(
            "{} (corrected defaults; UD-387 switch {}, UD-388 switch {}): {n} values bitwise",
            f.case_id(),
            sw.in_block_deviator_energy,
            sw.at1_strict_irreversibility_indicator
        );
    });
}

/// What the full corrected defaults change in the cases that need a
/// phase-field switch (where a cell needs an
/// upstream-compat switch to be bitwise, the default mode is also run and
/// what differs is stated). Every such case is run with every default
/// corrected (no switch at all) and compared with the oracle: the first
/// step whose digest line differs, which digests differ there, and the
/// largest relative differences of the per-step dissipated and potential
/// energies and of the final nodal damage and material stress. The test
/// requires that each run differs from upstream (otherwise the switch would
/// be unnecessary and the replay's claim stale) and that the default run
/// itself is sound: no failure, nodal damage finite and its range printed.
/// The measured values are recorded in docs/NUMERICAL_VALIDATION.md.
#[test]
fn coupler_solid_phase_field_default_mode_differences() {
    let mut measured = 0;
    for f in cases(AREA, "pf_") {
        let sw = pf_switches(f.case_id());
        if sw == akantu_phase_field::PhaseFieldUpstreamCompat::default() {
            continue;
        }
        let cid = f.case_id().to_owned();
        let mut c = build_pf(&f, false, None);
        let sid = solver_id(&f, "solid_solver_id");
        let pid = solver_id(&f, "phase_solver_id");
        let save = param(&f, "save_previous_state").as_bool().unwrap();
        let bottom = param(&f, "bottom").as_f64().unwrap();
        let top = param(&f, "top").as_f64().unwrap();
        let schedule = f64s(&f, "schedule/strain");
        let digests = read_input_text(&f, "digests");
        let mut lines = digests.lines();
        let (mut e_diss, mut e_pot) = (Vec::new(), Vec::new());
        let mut first: Option<(usize, Vec<&str>)> = None;
        let names = [
            "displacement",
            "damage",
            "material damage",
            "material stress",
            "law damage",
            "law strain",
        ];
        for (s, &eps) in schedule.iter().enumerate() {
            apply_displacement(&mut c, eps, bottom, top);
            c.solve(sid.as_deref(), pid.as_deref())
                .unwrap_or_else(|e| panic!("{cid} (defaults): step {s}: {e}"));
            e_diss.push(c.phase.energy("dissipated").unwrap());
            e_pot.push(c.solid.energy("potential").unwrap());
            if save {
                c.phase.save_previous_state().unwrap();
            }
            let got = pf_digest_line(s, &c);
            let want = lines.next().unwrap();
            if first.is_none() && got != want {
                let differ = got
                    .split(' ')
                    .zip(want.split(' '))
                    .skip(1)
                    .zip(names)
                    .filter(|((a, b), _)| a != b)
                    .map(|(_, n)| n)
                    .collect();
                first = Some((s, differ));
            }
        }
        let max_rel = |got: &[f64], want: &[f64]| -> f64 {
            assert_eq!(got.len(), want.len());
            let scale = want.iter().fold(0.0_f64, |m, x| m.max(x.abs()));
            got.iter()
                .zip(want)
                .fold(0.0_f64, |m, (a, b)| m.max((a - b).abs()))
                / scale.max(f64::MIN_POSITIVE)
        };
        let d = c.phase.damage().unwrap().as_slice().to_vec();
        assert!(d.iter().all(|x| x.is_finite()), "{cid}: damage not finite");
        let (dmin, dmax) = d
            .iter()
            .fold((f64::INFINITY, f64::NEG_INFINITY), |(a, b), &x| {
                (a.min(x), b.max(x))
            });
        let r_diss = max_rel(&e_diss, &f64s(&f, "energy/dissipated"));
        let r_pot = max_rel(&e_pot, &f64s(&f, "energy/potential"));
        let r_d = max_rel(&d, &f64s(&f, "final/damage"));
        let r_s = max_rel(
            &material_internal(&c, 0, "stress"),
            &f64s(&f, "final/material/0/stress"),
        );
        let (s0, which) = first.unwrap_or_else(|| {
            panic!(
                "{cid}: the full defaults replay upstream bit for bit: the switch is unnecessary"
            )
        });
        eprintln!(
            "INFO {cid} (full defaults; needs UD-387 {} / UD-388 {}): first differing step {s0} \
             ({which:?}); max rel. difference (to the oracle's max |.|): dissipated energy \
             {r_diss:.3e}, potential energy {r_pot:.3e}, final nodal damage {r_d:.3e}, final \
             material stress {r_s:.3e}; final damage range [{dmin:.6e}, {dmax:.6e}]",
            sw.in_block_deviator_energy, sw.at1_strict_irreversibility_indicator
        );
        measured += 1;
    }
    assert_eq!(measured, 5, "pf_deviatoric and the four accuracy cases");
}

/// The first step of a corrected-defaults replay of `f` with the
/// phase-field switches `sw` whose digest line differs from the oracle's,
/// with the names of the differing digests (`None`: bit for bit).
fn first_pf_difference(
    f: &Fixture,
    sw: akantu_phase_field::PhaseFieldUpstreamCompat,
) -> Option<(usize, Vec<&'static str>)> {
    let cid = f.case_id().to_owned();
    let mut c = build_pf(f, false, Some(sw));
    let sid = solver_id(f, "solid_solver_id");
    let pid = solver_id(f, "phase_solver_id");
    let save = param(f, "save_previous_state").as_bool().unwrap();
    let bottom = param(f, "bottom").as_f64().unwrap();
    let top = param(f, "top").as_f64().unwrap();
    let schedule = f64s(f, "schedule/strain");
    let digests = read_input_text(f, "digests");
    let mut lines = digests.lines();
    let names = [
        "displacement",
        "damage",
        "material damage",
        "material stress",
        "law damage",
        "law strain",
    ];
    for (s, &eps) in schedule.iter().enumerate() {
        apply_displacement(&mut c, eps, bottom, top);
        c.solve(sid.as_deref(), pid.as_deref())
            .unwrap_or_else(|e| panic!("{cid} ({sw:?}): step {s}: {e}"));
        if save {
            c.phase.save_previous_state().unwrap();
        }
        let got = pf_digest_line(s, &c);
        let want = lines.next().unwrap();
        if got != want {
            let differ = got
                .split(' ')
                .zip(want.split(' '))
                .skip(1)
                .zip(names)
                .filter(|((a, b), _)| a != b)
                .map(|(_, n)| n)
                .collect();
            return Some((s, differ));
        }
    }
    None
}

/// Each switch of a cell that needs two
/// is necessary on its own. A `pf_*` case whose bitwise replay needs both
/// UD-387 and UD-388 (`pf_linear_deviatoric_penalization`) is replayed
/// once without each (the other kept, every other default corrected): both
/// runs must differ from the oracle; with both switches the replay is
/// bitwise (`coupler_solid_phase_field_corrected_single_law_identical`).
/// [`coupler_solid_phase_field_default_mode_differences`] drops both at
/// once, which shows only that at least one is needed.
#[test]
fn coupler_solid_phase_field_two_switch_cells_leave_one_out() {
    let mut cells = 0;
    for f in cases(AREA, "pf_") {
        let sw = pf_switches(f.case_id());
        if !(sw.in_block_deviator_energy && sw.at1_strict_irreversibility_indicator) {
            continue;
        }
        cells += 1;
        let without_ud387 = akantu_phase_field::PhaseFieldUpstreamCompat {
            in_block_deviator_energy: false,
            ..sw
        };
        let without_ud388 = akantu_phase_field::PhaseFieldUpstreamCompat {
            at1_strict_irreversibility_indicator: false,
            ..sw
        };
        for (what, run) in [
            ("without UD-387", without_ud387),
            ("without UD-388", without_ud388),
        ] {
            let (s0, which) = first_pf_difference(&f, run).unwrap_or_else(|| {
                panic!(
                    "{}: {what} the replay is still bit for bit: that switch is unnecessary",
                    f.case_id()
                )
            });
            eprintln!(
                "INFO {} ({what}, the other switch kept): first differing step {s0} ({which:?})",
                f.case_id()
            );
        }
    }
    assert_eq!(cells, 1, "pf_linear_deviatoric_penalization");
}

