/// `contact_static_hertz` replayed with the coupler's switches on
/// (`SolidContactCompat::upstream()`: the compat replay) and off (the
/// corrected defaults). UD-374: the case is frictionless (`mu = 0`), the
/// friction history never reaches a force or a modulus. UD-1291: the load
/// increments act on the `loading` edge only, which no contact node belongs
/// to, so the search before the first residual finds the previous step's
/// last search. Both settings must reproduce the oracle bitwise.
#[test]
fn coupler_solid_contact_static_fixture() {
    for compat in [
        SolidContactCompat::upstream(),
        SolidContactCompat::default(),
    ] {
        replay_contact_static_hertz(compat);
    }
}

fn replay_contact_static_hertz(compat: SolidContactCompat) {
    let f = &cases(AREA, "contact_static_hertz")[0];
    let cid = format!("{} ({compat:?})", f.case_id());
    let mesh = read_mesh(&f.input_path("mesh").unwrap(), 2);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    let selector = PhysicalSurfaceSelector::new(&mesh, &parser).unwrap();
    let mut c = CouplerSolidContact::with_parser(
        SharedMesh::new(mesh),
        None,
        "coupler_solid_contact",
        parser,
    )
    .unwrap();
    c.solid
        .set_material_selector(Box::new(ElementDataSelector::new("physical_names")));
    c.init_full(&eigen_static()).unwrap();
    c.contact.set_surface_selector(Box::new(selector)).unwrap();
    // UD-002 (node-indexed stiffness, assigned forces), UD-363/364/365,
    // UD-368 (upstream normal moduli: they drive the Newton path)
    c.contact.set_upstream_compat(ContactUpstreamCompat::all());
    c.set_upstream_compat(compat).unwrap();
    let fix = |axis| FixedValue { value: 0.0, axis };
    c.apply_dirichlet_bc(&fix(SpatialDirection::X), "fixed")
        .unwrap();
    c.apply_dirichlet_bc(&fix(SpatialDirection::Y), "fixed")
        .unwrap();
    c.apply_dirichlet_bc(&fix(SpatialDirection::X), "loading")
        .unwrap();
    c.apply_dirichlet_bc(&fix(SpatialDirection::X), "symmetry")
        .unwrap();
    let steps = param(f, "steps").as_i64().unwrap() as usize;
    // the probe's literal (not the manifest's JSON float, see replay_cohesive)
    let inc: Real = -1e-4;
    assert!((inc - param(f, "increment").as_f64().unwrap()).abs() <= 1e-20);
    let digests = read_input_text(f, "digests");
    let mut lines = digests.lines();
    let (mut it, mut err, mut nb) = (Vec::new(), Vec::new(), Vec::new());
    let mut compared = 0;
    for s in 0..steps {
        let i = IncrementValue {
            value: inc,
            axis: SpatialDirection::Y,
        };
        c.apply_dirichlet_bc(&i, "loading").unwrap();
        c.solve_step(None)
            .unwrap_or_else(|e| panic!("{cid}: step {s}: {e}"));
        let (a, b) = newton_state(c.solid.solver.non_linear_solver(None).unwrap());
        it.push(a);
        err.push(b);
        nb.push(c.contact.contact_elements().len() as i64);
        let got = format!(
            "{s} {} {} {}",
            sha_hex(c.displacement().unwrap().as_slice()),
            sha_hex(c.contact.internal_force().as_slice()),
            sha_hex(c.contact.gaps().as_slice())
        );
        let line = lines.next().unwrap();
        let ck = format!("step_{s}");
        if line != got && f.quantity(&format!("{ck}/displacement")).is_ok() {
            assert_bits(
                &cid,
                &format!("{ck}/displacement"),
                c.displacement().unwrap().as_slice(),
                &f64s(f, &format!("{ck}/displacement")),
            );
        }
        assert_eq!(line, got, "{cid}: step {s}: digests");
        compared += 3;
        if f.quantity(&format!("{ck}/displacement")).is_ok() {
            for (what, got) in [
                ("displacement", c.displacement().unwrap().as_slice()),
                (
                    "internal_force",
                    c.solid.internal_force().unwrap().as_slice(),
                ),
                ("contact_force", c.contact.internal_force().as_slice()),
                ("gaps", c.contact.gaps().as_slice()),
                ("normals", c.contact.normals().as_slice()),
                ("areas", c.contact.nodal_area().as_slice()),
            ] {
                let name = format!("{ck}/{what}");
                let e = f64s(f, &name);
                assert_bits(&cid, &name, got, &e);
                compared += e.len();
            }
        }
    }
    assert_eq!(it, i64s(f, "newton/iterations"), "{cid}: Newton iterations");
    assert_bits(&cid, "newton/error", &err, &f64s(f, "newton/error"));
    assert_eq!(
        nb,
        i64s(f, "nb_contact_elements"),
        "{cid}: contact elements"
    );
    for (name, mat) in [
        ("final/stress_upper", "upper"),
        ("final/stress_lower", "lower"),
    ] {
        let got = c
            .solid
            .material_by_name(mat)
            .unwrap()
            .base()
            .stress
            .get(ElementType::Quadrangle4, NG)
            .unwrap()
            .as_slice()
            .to_vec();
        let e = f64s(f, name);
        assert_bits(&cid, name, &got, &e);
        compared += e.len();
    }
    eprintln!("{cid}: {steps} steps, {compared} values bitwise");
}

