fn cohesive_setup(f: &Fixture) -> CouplerSolidCohesiveContact {
    let mesh = read_mesh(&f.input_path("mesh").unwrap(), 2);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    let mut c = CouplerSolidCohesiveContact::with_parser(
        SharedMesh::new(mesh),
        None,
        "coupler_solid_contact",
        parser,
    )
    .unwrap();
    let sel = MeshDataMaterialCohesiveSelector {
        default: c.solid.default_cohesive_selector(),
    };
    c.solid.set_material_selector(Box::new(sel));
    c.contact
        .set_surface_selector(Box::new(CohesiveSurfaceSelector::new()))
        .unwrap();
    c.init_full(&ModelOptions::new(AnalysisMethod::ExplicitLumpedMass), true)
        .unwrap();
    // UD-002 (assigned forces, ½ for the deformable master of the example)
    c.contact.set_upstream_compat(ContactUpstreamCompat::all());
    let fix = FixedValue {
        value: 0.0,
        axis: SpatialDirection::X,
    };
    c.apply_dirichlet_bc(&fix, "sides").unwrap();
    let dt = f64s(f, "time_step")[0];
    assert_bits(
        f.case_id(),
        "time_step",
        &[c.stable_time_step().unwrap() * 0.1],
        &[dt],
    );
    c.set_time_step(dt, None).unwrap();
    c
}

/// `through_solid`: insert with `solid.check_cohesive_stress()` (the
/// upstream example's own pattern, `cohesive_contact_explicit_dynamic.cc`)
/// instead of the coupler's; the new cohesive elements then reach the
/// contact surface through the next `solve_step` (coupler) or a
/// [`CohesiveForwarder`] (stand-alone callback) — the
/// probe inserted through the coupler, so the trajectories must agree
/// bitwise (mutant M9 dies).
fn replay_cohesive(f: &Fixture, through_solid: bool) -> usize {
    let cid = format!("{} (through_solid = {through_solid})", f.case_id());
    let callback = param(f, "callback").as_bool().unwrap();
    let mut c = cohesive_setup(f);
    let shared = {
        use akantu_model::Model;
        c.solid.smm.mesh().clone()
    };
    let mut forwarder = CohesiveForwarder::new(&shared).unwrap();
    let steps = param(f, "steps").as_i64().unwrap() as usize;
    let load = param(f, "loading_steps").as_i64().unwrap() as usize;
    // the probe's `1e-3 / Real(load)` (the manifest's JSON float is not read
    // back: serde_json's default float parser is not correctly rounded)
    let inc = 1e-3 / load as Real;
    assert!((inc - param(f, "increment").as_f64().unwrap()).abs() <= 1e-20);
    let digests = read_input_text(f, "digests");
    let mut lines = digests.lines();
    let (mut nb, mut ins, mut epot, mut ekin) = (Vec::new(), Vec::new(), Vec::new(), Vec::new());
    let mut n_ins = 0i64;
    let mut compared = 0;
    for s in 0..steps {
        let i = if s < load { inc } else { -inc };
        let up = IncrementValue {
            value: i,
            axis: SpatialDirection::Y,
        };
        let down = IncrementValue {
            value: -i,
            axis: SpatialDirection::Y,
        };
        c.apply_dirichlet_bc(&up, "loading").unwrap();
        c.apply_dirichlet_bc(&down, "fixed").unwrap();
        if callback {
            if through_solid {
                forwarder.forward(&shared, &mut c.contact).unwrap();
            } else {
                c.forward_new_cohesive_elements().unwrap();
            }
            let contact = &mut c.contact;
            c.solid
                .smm
                .solve_step_with(None, |physics, solver, id| {
                    let mut cohesive = akantu_cohesive::model::CohesiveCallback::new(physics);
                    let mut cb = CohesiveContactSolverCallback::new(
                        &mut cohesive,
                        contact,
                        AnalysisMethod::ExplicitLumpedMass,
                    );
                    solver.solve_step(cb.as_callback(), id)
                })
                .unwrap();
        } else {
            c.solve_step(None).unwrap();
        }
        n_ins += if through_solid {
            c.solid.check_cohesive_stress().unwrap()
        } else {
            c.check_cohesive_stress().unwrap()
        } as i64;
        let gaps = c.contact.gaps().as_slice().to_vec();
        let mut v = c.solid.smm.velocity_mut().unwrap();
        for (g, vel) in gaps.iter().zip(v.as_mut_slice().as_chunks_mut::<2>().0) {
            if *g > 0.0 {
                for x in vel {
                    *x *= 0.99;
                }
            }
        }
        drop(v);
        nb.push(c.contact.contact_elements().len() as i64);
        ins.push(n_ins);
        if s % 10 == 0 || s == steps - 1 {
            let got = format!(
                "{s} {} {}",
                sha_hex(c.solid.smm.displacement().unwrap().as_slice()),
                sha_hex(c.contact.internal_force().as_slice())
            );
            let line = lines.next().unwrap();
            let ck = format!("step_{s}/displacement");
            if line != got && f.quantity(&ck).is_ok() {
                assert_bits(
                    &cid,
                    &ck,
                    c.solid.smm.displacement().unwrap().as_slice(),
                    &f64s(f, &ck),
                );
            }
            assert_eq!(line, got, "{cid}: step {s}: digests");
            compared += 2;
            epot.push(c.solid.energy("potential").unwrap());
            ekin.push(c.solid.energy("kinetic").unwrap());
        }
        let ck = format!("step_{s}");
        if f.quantity(&format!("{ck}/displacement")).is_ok() {
            for (what, got) in [
                (
                    "displacement",
                    c.solid.smm.displacement().unwrap().as_slice(),
                ),
                ("velocity", c.solid.smm.velocity().unwrap().as_slice()),
                ("contact_force", c.contact.internal_force().as_slice()),
                ("gaps", c.contact.gaps().as_slice()),
                ("areas", c.contact.nodal_area().as_slice()),
            ] {
                let name = format!("{ck}/{what}");
                let e = f64s(f, &name);
                assert_bits(&cid, &name, got, &e);
                compared += e.len();
            }
        }
    }
    assert_eq!(
        nb,
        i64s(f, "nb_contact_elements"),
        "{cid}: contact elements"
    );
    assert_eq!(
        ins,
        i64s(f, "inserted"),
        "{cid}: inserted cohesive elements"
    );
    assert!(*ins.last().unwrap() > 0, "{cid}: no insertion");
    assert!(nb.iter().any(|&n| n > 0), "{cid}: no contact");
    assert_bits(
        &cid,
        "energy/potential",
        &epot,
        &f64s(f, "energy/potential"),
    );
    assert_bits(&cid, "energy/kinetic", &ekin, &f64s(f, "energy/kinetic"));
    compared + epot.len() + ekin.len()
}

#[test]
fn coupler_solid_cohesive_contact_fixtures() {
    let all = cases(AREA, "cohesive_contact_");
    assert_eq!(all.len(), 2, "expected the 2 cohesive_contact_* cases");
    for f in all {
        for through_solid in [false, true] {
            let n = replay_cohesive(&f, through_solid);
            eprintln!(
                "{} (through_solid = {through_solid}): {n} values bitwise",
                f.case_id()
            );
        }
    }
}

/// The coupler with **Coulomb friction on
/// the faces of a new crack** against the oracle (case
/// `friction_cohesive_contact_explicit`, probe `couplers_probe` version 4,
/// UD-001 zero-initialisation variant of the oracle: upstream's friction
/// reads uninitialised workspaces otherwise). The example's set-up with
/// `mu = 0.3`, `epsilon_n = epsilon_t = 1e3`, the bottom blocked in x
/// instead of the sides, the example's loading / unloading in y and, from
/// step 5000 (crack closed, compression), a shear increment in x on
/// `loading`: insertion, contact of the crack faces, stick and slip.
/// Replayed with the contact's upstream switches (`all()`, as the other
/// explicit cohesive-contact cases: UD-002 assignment of the forces with ½
/// on the deformable master; UD-001 has no switch, the port zero-initialises
/// always): every 10 steps the digests of the displacement, the contact
/// force, the tangential force and the tangential tractions; after every
/// step the contact, insertion, stick and slip counts; the energies; the
/// full arrays (contact states included) at the checkpoints — bit for bit.
/// The run must reach both stick and slip.
#[test]
fn coupler_cohesive_contact_friction_fixture() {
    let all = cases(AREA, "friction_cohesive_contact_explicit");
    assert_eq!(
        all.len(),
        1,
        "the oracle case friction_cohesive_contact_explicit"
    );
    let f = &all[0];
    let cid = f.case_id().to_owned();
    let mesh = read_mesh(&f.input_path("mesh").unwrap(), 2);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    let mut c = CouplerSolidCohesiveContact::with_parser(
        SharedMesh::new(mesh),
        None,
        "coupler_solid_contact",
        parser,
    )
    .unwrap();
    let sel = MeshDataMaterialCohesiveSelector {
        default: c.solid.default_cohesive_selector(),
    };
    c.solid.set_material_selector(Box::new(sel));
    c.contact
        .set_surface_selector(Box::new(CohesiveSurfaceSelector::new()))
        .unwrap();
    c.init_full(&ModelOptions::new(AnalysisMethod::ExplicitLumpedMass), true)
        .unwrap();
    c.contact.set_upstream_compat(ContactUpstreamCompat::all());
    let fix = FixedValue {
        value: 0.0,
        axis: SpatialDirection::X,
    };
    c.apply_dirichlet_bc(&fix, "fixed").unwrap();
    let dt = f64s(f, "time_step")[0];
    assert_bits(
        &cid,
        "time_step",
        &[c.stable_time_step().unwrap() * 0.1],
        &[dt],
    );
    c.set_time_step(dt, None).unwrap();
    let steps = param(f, "steps").as_i64().unwrap() as usize;
    let load = param(f, "loading_steps").as_i64().unwrap() as usize;
    let shear_from = param(f, "shear_from").as_i64().unwrap() as usize;
    // the probe's `1e-3 / Real(load)` (not the manifest's JSON float)
    let inc = 1e-3 / load as Real;
    let shear = 1e-3 / load as Real;
    let digests = read_input_text(f, "digests");
    let mut lines = digests.lines();
    let (mut nb, mut ins, mut stick, mut slip) = (Vec::new(), Vec::new(), Vec::new(), Vec::new());
    let (mut epot, mut ekin) = (Vec::new(), Vec::new());
    let mut n_ins = 0i64;
    let mut compared = 0;
    let code = |s: akantu_core::enums::ContactState| -> i64 {
        match s {
            akantu_core::enums::ContactState::NoContact => 0,
            akantu_core::enums::ContactState::Stick => 1,
            akantu_core::enums::ContactState::Slip => 2,
        }
    };
    for s in 0..steps {
        let i = if s < load { inc } else { -inc };
        let up = IncrementValue {
            value: i,
            axis: SpatialDirection::Y,
        };
        let down = IncrementValue {
            value: -i,
            axis: SpatialDirection::Y,
        };
        c.apply_dirichlet_bc(&up, "loading").unwrap();
        c.apply_dirichlet_bc(&down, "fixed").unwrap();
        if s >= shear_from {
            let sx = IncrementValue {
                value: shear,
                axis: SpatialDirection::X,
            };
            c.apply_dirichlet_bc(&sx, "loading").unwrap();
        }
        c.solve_step(None).unwrap();
        n_ins += c.check_cohesive_stress().unwrap() as i64;
        let gaps = c.contact.gaps().as_slice().to_vec();
        let mut v = c.solid.smm.velocity_mut().unwrap();
        for (g, vel) in gaps.iter().zip(v.as_mut_slice().as_chunks_mut::<2>().0) {
            if *g > 0.0 {
                for x in vel {
                    *x *= 0.99;
                }
            }
        }
        drop(v);
        nb.push(c.contact.contact_elements().len() as i64);
        ins.push(n_ins);
        let states = c.contact.contact_state().as_slice().to_vec();
        let (mut st, mut sl) = (0i64, 0i64);
        for el in c.contact.contact_elements() {
            match code(states[el.slave as usize]) {
                1 => st += 1,
                2 => sl += 1,
                _ => {}
            }
        }
        stick.push(st);
        slip.push(sl);
        let tangential_force = c
            .contact
            .nodal_field_real("tangential_force")
            .unwrap()
            .as_slice()
            .to_vec();
        if s % 10 == 0 || s == steps - 1 {
            let got = format!(
                "{s} {} {} {} {}",
                sha_hex(c.solid.smm.displacement().unwrap().as_slice()),
                sha_hex(c.contact.internal_force().as_slice()),
                sha_hex(&tangential_force),
                sha_hex(c.contact.tangential_tractions().as_slice())
            );
            let line = lines.next().unwrap();
            let ck = format!("step_{s}/displacement");
            if line != got && f.quantity(&ck).is_ok() {
                assert_bits(
                    &cid,
                    &ck,
                    c.solid.smm.displacement().unwrap().as_slice(),
                    &f64s(f, &ck),
                );
            }
            assert_eq!(line, got, "{cid}: step {s}: digests");
            compared += 4;
            epot.push(c.solid.energy("potential").unwrap());
            ekin.push(c.solid.energy("kinetic").unwrap());
        }
        let ck = format!("step_{s}");
        if f.quantity(&format!("{ck}/displacement")).is_ok() {
            for (what, got) in [
                (
                    "displacement",
                    c.solid.smm.displacement().unwrap().as_slice().to_vec(),
                ),
                (
                    "velocity",
                    c.solid.smm.velocity().unwrap().as_slice().to_vec(),
                ),
                (
                    "contact_force",
                    c.contact.internal_force().as_slice().to_vec(),
                ),
                ("tangential_force", tangential_force.clone()),
                ("gaps", c.contact.gaps().as_slice().to_vec()),
                ("areas", c.contact.nodal_area().as_slice().to_vec()),
                (
                    "tangential_tractions",
                    c.contact.tangential_tractions().as_slice().to_vec(),
                ),
            ] {
                let name = format!("{ck}/{what}");
                let e = f64s(f, &name);
                assert_bits(&cid, &name, &got, &e);
                compared += e.len();
            }
            let name = format!("{ck}/contact_state");
            let got: Vec<i64> = states.iter().map(|&x| code(x)).collect();
            assert_eq!(got, i64s(f, &name), "{cid}: {name}");
            compared += got.len();
        }
    }
    for (name, got) in [
        ("nb_contact_elements", &nb),
        ("inserted", &ins),
        ("nb_stick", &stick),
        ("nb_slip", &slip),
    ] {
        assert_eq!(*got, i64s(f, name), "{cid}: {name}");
        compared += got.len();
    }
    assert_bits(
        &cid,
        "energy/potential",
        &epot,
        &f64s(f, "energy/potential"),
    );
    assert_bits(&cid, "energy/kinetic", &ekin, &f64s(f, "energy/kinetic"));
    compared += epot.len() + ekin.len();
    assert!(*ins.last().unwrap() > 0, "{cid}: no insertion");
    assert!(stick.iter().any(|&n| n > 0), "{cid}: no sticking contact");
    assert!(slip.iter().any(|&n| n > 0), "{cid}: no slipping contact");
    eprintln!(
        "{cid}: {compared} values bitwise; {} insertions; steps with stick {} / slip {}",
        ins.last().unwrap(),
        stick.iter().filter(|&&n| n > 0).count(),
        slip.iter().filter(|&&n| n > 0).count()
    );
}

/// The SolidPart trait object of the plain solid (compile-time check that
/// the coupler's callback is usable on `SolidMechanicsPhysics`).
#[allow(dead_code)] // compile-time check only
fn _solid_part_is_object_safe(
    p: &mut akantu_solid::model::SolidMechanicsPhysics,
) -> &mut dyn SolidPart {
    p
}
